/**
 * MettleUp's mark and wordmark as scene nodes (Phase 3 share pictures). The mark is logo E
 * "Forged" (first MettleUp release, 0.56.0): the same faces as components/brand/MettleUpLogo, from
 * components/brand/mettleUpMark.ts, the M cut out so the picture shows through it.
 *
 * The name is the "steel plate" wordmark (owner pick, R-259, 31 Oct 2026), drawn as paths from the
 * same mettleUpMark.ts (generated by branding/mettleup/_src/steel_wordmark.py --ts), never typed in
 * a font. Share pictures are small sizes, so it is flat (BRAND.md "Type"): "METTLE" in Iron, "UP"
 * in Forge orange.
 *
 * Gym branding (D6): MettleUp's mark is MettleUp's: its faces and the name are drawn in MettleUp's
 * own fixed colours, whatever gym look the app wears (the picture's other parts take the gym's
 * colours from the tokens).
 */
import { MARK_BOX, MARK_FACES, METTLEUP_COLOURS, WORDMARK_BOX, WORDMARK_METTLE_D, WORDMARK_UP_D } from '@/components/brand/mettleUpMark';

import type { SceneNode } from './scene';

/** MettleUp's own colours (BRAND.md), never the gym's. */
export const FORGE_MARK = METTLEUP_COLOURS;
/** "METTLE" in the flat wordmark (BRAND.md: Iron). */
export const IRON = '#E8EAEE';

/** The name's cap height as a share of the mark, as the app's lockup (MettleUpLogo, CAP). */
const CAP = 0.44;
/** The gap between the mark and the name, as the app's lockup. */
const GAP = 0.32;
/** BRAND.md: below a 20 px cap height the lockup is not used (the mark alone instead). */
export const MIN_CAP = 20;

/** The Forged hex mark, `size` pixels square, top-left at (x, y); the hex's points touch top and bottom. */
export function logoMark(x: number, y: number, size: number): SceneNode[] {
  const k = size / MARK_BOX.size;
  return MARK_FACES.map((f): SceneNode => ({ t: 'path', d: f.d, fill: f.fill, x: x - MARK_BOX.x * k, y: y - MARK_BOX.y * k, scale: k }));
}

/**
 * "METTLE" and "UP" in the steel letters, cap height `cap`, top-left of the M at (x, top). The two
 * paths, and the name's width. PURE.
 */
export function steelName(x: number, top: number, cap: number): { nodes: SceneNode[]; width: number } {
  const k = cap / WORDMARK_BOX.h;
  return {
    nodes: [
      { t: 'path', d: WORDMARK_METTLE_D, fill: IRON, x, y: top, scale: k },
      { t: 'path', d: WORDMARK_UP_D, fill: FORGE_MARK.forge, x, y: top, scale: k },
    ],
    width: WORDMARK_BOX.w * k,
  };
}

/**
 * Mark + the steel "METTLEUP", the name's cap box centred on the mark's middle. `size` is the mark's
 * square (top-left at x, y); `cap` the name's cap height (default 0.44 x size, as the app's lockup,
 * never under MIN_CAP). Returns its width too. PURE.
 */
export function wordmark(x: number, y: number, size: number, cap?: number): { nodes: SceneNode[]; width: number } {
  const c = Math.max(MIN_CAP, cap ?? size * CAP);
  const gap = size * GAP;
  const name = steelName(x + size + gap, y + size / 2 - c / 2, c);
  return { nodes: [...logoMark(x, y, size), ...name.nodes], width: size + gap + name.width };
}
